if (points.size() < 3) return points;

std::vector<cg3::Point2d> sorted = points;
std::sort(sorted.begin(), sorted.end());

std::vector<cg3::Point2d> hull;

auto cross = [](const cg3::Point2d& O, const cg3::Point2d& A, const cg3::Point2d& B) {
    return (A.x() - O.x()) * (B.y() - O.y()) - (A.y() - O.y()) * (B.x() - O.x());
};

for (size_t i = 0; i < sorted.size(); ++i) {
    while (hull.size() >= 2 && cross(hull[hull.size() - 2], hull.back(), sorted[i]) <= 0)
        hull.pop_back();
    hull.push_back(sorted[i]);
}

size_t lower_hull_size = hull.size();
for (int i = static_cast<int>(sorted.size()) - 2; i >= 0; --i) {
    while (hull.size() > lower_hull_size && cross(hull[hull.size() - 2], hull.back(), sorted[i]) <= 0)
        hull.pop_back();
    hull.push_back(sorted[i]);
}

hull.pop_back();
return hull;

